              /** Prefer `#dropdown-dom` menu row — **`li`** filter avoids strict-mode ambiguity with nested `span` + `.or()`. */
              const fromDropdownDomLi = page
                .locator('[id="dropdown-dom"] li[data-test-id^="cs-dropdown-elements"]')
